import Papa from 'papaparse'

import { downloadBlob } from '@/lib/download'
import { getTaskTypePriorityOfProd } from '@/lib/productions'
import { getPercentage } from '@/lib/stats'
import stringHelpers from '@/lib/string'
import {
  getDayRange,
  getMonthRange,
  getWeekRange,
  minutesToDays
} from '@/lib/time'
import { convertHours } from '@/lib/timesheet'

// The errors of the imported files the browser could not read (moved,
// deleted or changed since they were picked) and of the empty ones.
const readFailures = new WeakSet()

const addReadFailure = err => {
  if (Object(err) === err) readFailures.add(err)
}

// Windows-1252 leaves these bytes undefined: its decoder turns them into
// invisible control characters.
const WINDOWS_1252_UNDEFINED_BYTES = [0x81, 0x8d, 0x8f, 0x90, 0x9d]

// The characters beyond ASCII that UTF-8 does read, its "�" aside.
const UTF8_NON_ASCII = /[\u0080-\ufffc\ufffe\uffff]/g

// A spreadsheet saves a plain "CSV" in the encoding of the system,
// Windows-1252 in Western Europe and the Americas: read as UTF-8, its accented
// letters would turn into "�". A file that is not valid UTF-8 reads as
// Windows-1252, unless it holds a byte Windows-1252 leaves undefined (another
// encoding) or UTF-8 reads more of its characters beyond ASCII than it fails
// on (a UTF-8 file with a stray byte): it then reads as UTF-8, as before. A
// few bytes of Windows-1252 text can make a UTF-8 character, as "é", a
// no-break space, and "»" make "頻", but rarely more than the letters UTF-8
// fails on. A byte order mark still wins: FileReader follows it whatever
// encoding it is given.
const getFileEncoding = async file => {
  const bytes = new Uint8Array(
    await file.arrayBuffer().catch(err => {
      addReadFailure(err)
      throw err
    })
  )
  try {
    new TextDecoder('utf-8', { fatal: true }).decode(bytes)
    return 'UTF-8'
  } catch {
    const text = new TextDecoder().decode(bytes)
    const isWindows1252 =
      !bytes.some(byte => WINDOWS_1252_UNDEFINED_BYTES.includes(byte)) &&
      (text.match(UTF8_NON_ASCII) || []).length <=
        text.split('\ufffd').length - 1
    return isWindows1252 ? 'windows-1252' : 'UTF-8'
  }
}

const ESTIMATIONS_PARENTS = {
  Asset: { field: 'asset_type_name', labelKey: 'tasks.fields.asset_type' },
  Edit: { field: 'episode_name', labelKey: 'shots.fields.episode' },
  Sequence: { field: 'episode_name', labelKey: 'shots.fields.episode' },
  Shot: { field: 'sequence_name', labelKey: 'tasks.fields.sequence' }
}

/*
 * The columns of a task type export that the estimations import of Zou
 * reads, by the name Zou reads, with the key of their label: the export
 * writes these labels and the import gives them their name back. The parent
 * of a sequence or an edit is its episode, so only a TV show has one, and an
 * episode has none.
 */
export const getEstimationsCsvLabelKeys = (
  entityType,
  { isPaperProduction = false, isTVShow = false } = {}
) => {
  const hasParent =
    ESTIMATIONS_PARENTS[entityType] &&
    (isTVShow || !['Edit', 'Sequence'].includes(entityType))
  return {
    ...(hasParent && { Parent: ESTIMATIONS_PARENTS[entityType].labelKey }),
    Entity: 'tasks.fields.entity_name',
    ...(isPaperProduction && { Drawings: 'tasks.fields.drawings' }),
    Difficulty: 'tasks.fields.difficulty',
    Estimation: 'tasks.fields.estimation',
    'Start date': 'tasks.fields.start_date',
    'Due date': 'tasks.fields.due_date'
  }
}

export const getEstimationsParentField = entityType =>
  ESTIMATIONS_PARENTS[entityType]?.field

const getDescriptorCsvValue = (entity, descriptor, personMap) => {
  const value = entity.data[descriptor.field_name]
  if (descriptor.data_type === 'boolean') {
    return value?.toLowerCase() === 'true'
  }
  if (descriptor.data_type === 'person') {
    return personMap.get(value)?.full_name || ''
  }
  return value
}

/*
 * The lines of the export of an edit, sequence, or episode list: the
 * episode in a TV show, the name, the description, the values only the
 * entity type has, the metadata, the time spent and the estimation in days,
 * then the status and the assignees of each task type. A row received live
 * may have no task yet.
 */
export const getEntityCsvLines = (
  entities,
  {
    descriptors,
    extraValues = [],
    hasEpisode = false,
    isEstimation = false,
    isTime = false,
    organisation,
    personMap,
    taskMap,
    validationColumns = []
  }
) =>
  entities.map(entity => [
    ...(hasEpisode ? [entity.episode_name] : []),
    entity.name,
    entity.description || '',
    ...extraValues.map(getValue => getValue(entity)),
    ...descriptors.map(descriptor =>
      getDescriptorCsvValue(entity, descriptor, personMap)
    ),
    ...(isTime
      ? [minutesToDays(organisation, entity.timeSpent).toFixed(2)]
      : []),
    ...(isEstimation
      ? [minutesToDays(organisation, entity.estimation).toFixed(2)]
      : []),
    ...validationColumns.flatMap(taskTypeId => {
      const task = taskMap.get(entity.validations?.get(taskTypeId))
      if (!task) return ['', '']
      return [
        task.task_status_short_name,
        task.assignees
          .map(personId => personMap.get(personId)?.full_name)
          .filter(Boolean)
          .join(',')
      ]
    })
  ])

const csv = {
  generateTimesheet({
    name,
    timesheet,
    people,
    unit,
    dailyRates = {},
    organisation,
    detailLevel,
    todayYear,
    todayMonth,
    year,
    month,
    week
  }) {
    const headers = csv.getTimesheetHeaders(
      timesheet,
      detailLevel,
      todayYear,
      todayMonth,
      year,
      month,
      week
    )
    const entries = csv.getTimesheetEntries(
      organisation,
      unit,
      detailLevel,
      headers,
      people,
      timesheet,
      dailyRates
    )
    csv.buildCsvFile(name, entries)
  },

  getTimesheetHeaders(
    timesheet,
    detailLevel,
    todayYear,
    todayMonth,
    year,
    month,
    week
  ) {
    const headers = ['Person']
    let range = []
    if (detailLevel === 'year') {
      Object.keys(timesheet).forEach(yearLabel => {
        headers.push(yearLabel)
      })
    } else if (detailLevel === 'month') {
      range = getMonthRange(year, todayYear, todayMonth)
    } else if (detailLevel === 'week') {
      range = getWeekRange(year, todayYear)
    } else if (detailLevel === 'day') {
      range = getDayRange(year, month, todayYear, todayMonth)
    }
    for (const unit in range) {
      let value = parseInt(unit) + 1
      if (detailLevel === 'day') {
        value = `${year}-${String(month).padStart(2, 0)}-${String(value).padStart(2, 0)}`
      }
      headers.push(value)
    }
    return headers
  },

  getTimesheetEntries(
    organisation,
    unit,
    detailLevel,
    headers,
    people,
    timesheet,
    dailyRates = {}
  ) {
    const entries = [headers]
    const convert = (person, minutes) => {
      const value = convertHours(
        minutes / 60,
        unit,
        organisation,
        dailyRates[person.id]
      )
      return unit === 'salary' ? Math.round(value) : value
    }
    people.forEach(person => {
      const line = [person.full_name]
      if (detailLevel === 'year') {
        headers.forEach((h, index) => {
          if (index > 0) {
            if (timesheet[h] && timesheet[h][person.id]) {
              line.push(convert(person, timesheet[h][person.id]))
            } else {
              line.push('-')
            }
          }
        })
      } else {
        headers.forEach((h, index) => {
          if (index > 0) {
            if (timesheet && timesheet[index] && timesheet[index][person.id]) {
              line.push(convert(person, timesheet[index][person.id]))
            } else {
              line.push('-')
            }
          }
        })
      }
      entries.push(line)
    })
    return entries
  },

  /*
   * Build the budget export. When `expenses` is given (the "real costs" view
   * is active), the columns mirror the on-screen table: real cost per past
   * month, real total, estimated so far and gap, then the estimated future
   * months, remaining, real + remaining, estimated total and final gap.
   */
  generateBudget(
    t,
    departmentMap,
    personMap,
    nameData,
    currency,
    monthsBetweenProductionDates,
    totalEntry,
    budgetDepartments,
    expenses = null
  ) {
    const name = csv.generateName(nameData)
    const monthLabel = month =>
      month.month() === 0 ? month.format('MMM / YY') : month.format('MMM')
    const monthCells = (costs, months) =>
      months.map(month => costs?.[month.format('YYYY-MM')] || '')

    const pastMonths = expenses ? expenses.monthsBetweenStartAndNow : []
    const futureMonths = expenses
      ? expenses.monthsBetweenNowAndEnd
      : monthsBetweenProductionDates

    const headers = [
      t('budget.fields.department'),
      '',
      '',
      t('budget.fields.base_salary'),
      t('budget.fields.duration'),
      ...pastMonths.map(monthLabel),
      ...(expenses
        ? [
            t('budget.costs'),
            t('budget.previsional_costs'),
            t('budget.difference')
          ]
        : []),
      ...futureMonths.map(monthLabel),
      ...(expenses
        ? [t('budget.remaining'), t('budget.remaining_and_costs')]
        : []),
      `${t('main.total')} (${currency})`,
      ...(expenses ? [t('budget.difference')] : [])
    ]

    const costCells = (monthCosts, total, realCosts, done, remaining) => {
      if (!expenses) return [...monthCells(monthCosts, futureMonths), total]
      const real = realCosts?.total || 0
      return [
        ...monthCells(realCosts, pastMonths),
        real,
        done,
        done - real,
        ...monthCells(monthCosts, futureMonths),
        remaining,
        real + remaining,
        total,
        total - (real + remaining)
      ]
    }
    const realCosts = expenses?.convertedExpenses || {}
    const done = expenses?.donePrevisional || {}
    const remaining = expenses?.remainingPrevisional || {}

    const totalLine = [
      `${t('main.total')}`,
      '',
      '',
      '',
      '',
      ...costCells(
        totalEntry.monthCosts,
        totalEntry.total,
        realCosts,
        done.total || 0,
        remaining.total || 0
      )
    ]
    const entries = [totalLine]
    budgetDepartments.forEach(departmentEntry => {
      const department = departmentMap.get(departmentEntry.id)
      const departmentId = departmentEntry.id
      entries.push([
        department?.name || '',
        '',
        '',
        departmentEntry.monthly_salary,
        departmentEntry.months_duration,
        ...costCells(
          departmentEntry.monthCosts,
          departmentEntry.total,
          realCosts[departmentId],
          done[departmentId]?.total || 0,
          remaining[departmentId]?.total || 0
        )
      ])
      departmentEntry.persons.forEach(personEntry => {
        const entryId = personEntry.budget_entry_id
        entries.push([
          personEntry.position
            ? t('budget.positions.' + personEntry.position)
            : '',
          personEntry.seniority
            ? t('budget.seniorities.' + personEntry.seniority)
            : '',
          personEntry.person_id
            ? personMap.get(personEntry.person_id)?.name || ''
            : t('budget.new_hiring'),
          personEntry.monthly_salary,
          personEntry.months_duration,
          ...costCells(
            personEntry.monthCosts,
            personEntry.total,
            realCosts[departmentId]?.[personEntry.person_id],
            done[departmentId]?.[entryId] || 0,
            remaining[departmentId]?.[entryId] || 0
          )
        ])
      })
    })
    const lines = [headers, ...entries]
    return csv.buildCsvFile(name, lines)
  },

  generateName(nameData) {
    return stringHelpers.slugify(nameData.join('_'))
  },

  /*
   * Return the display names of the parsed CSV lines that don't match any
   * existing entity in the given lookup (those lines will be created by the
   * import instead of updating an existing entity). `indexMatchers` lists
   * the column indexes used to build the lookup keys.
   */
  getNewEntityNames(parsedCsv, indexMatchers, database) {
    const names = new Map()
    parsedCsv
      .slice(1)
      .filter(line => line.length > 1 || line[0])
      .forEach(line => {
        const values = indexMatchers.map(index => line[index] || '')
        const key = values.join('')
        if (key.length > 0 && !database[key] && !names.has(key)) {
          names.set(key, values.filter(value => value.length > 0).join(' / '))
        }
      })
    return [...names.values()]
  },

  /*
   * Give each header that is a label its name (`names` maps labels to
   * names), unless the file already has a header of that name or the label
   * is also the name of a column of its own, listed in `kept`.
   */
  renameHeaders(headers, names, kept = []) {
    return headers.map(header => {
      const name = names.get(header)
      return name && !headers.includes(name) && !kept.includes(header)
        ? name
        : header
    })
  },

  /*
   * Give each cell of the column `column` that is a label its value
   * (`names` maps lowercase labels to values), whatever its case and the
   * spaces around it. The other cells and columns stay as they are.
   */
  renameValues(entries, column, names) {
    const [headers = [], ...lines] = entries
    const index = headers.indexOf(column)
    if (index < 0) return entries
    return [
      headers,
      ...lines.map(line =>
        line.map((cell, cellIndex) => {
          const value =
            cellIndex === index && names.get(String(cell).trim().toLowerCase())
          return value || cell
        })
      )
    ]
  },

  // Drop the column `column`, header and cells. A file without it stays as
  // it is.
  removeColumn(entries, column) {
    const [headers = [], ...lines] = entries
    const index = headers.indexOf(column)
    if (index < 0) return entries
    const isKept = (cell, cellIndex) => cellIndex !== index
    return [headers.filter(isKept), ...lines.map(line => line.filter(isKept))]
  },

  turnEntriesToCsvString(entries, config = {}) {
    return Papa.unparse(entries, {
      delimiter: ';',
      // Neutralize spreadsheet formula injection: cells starting with
      // = + - @ are prefixed with ' so Excel/Sheets treat them as text.
      escapeFormulae: true,
      newline: '\n',
      quotes: true,
      skipEmptyLines: true,
      ...config
    })
  },

  buildCsvFile(name, entries) {
    const csvContent = csv.turnEntriesToCsvString(entries)
    downloadBlob(
      new Blob([csvContent], { type: 'text/csv;charset=utf-8' }),
      `${name}.csv`
    )
    return csvContent
  },

  generateStatReports(
    name,
    mainStats,
    taskTypeMap,
    taskStatusMap,
    entryMap,
    countMode,
    production
  ) {
    const headers = csv.getStatReportsHeaders(
      mainStats,
      taskTypeMap,
      production
    )
    const entries = csv.getStatReportsEntries(
      mainStats,
      taskTypeMap,
      taskStatusMap,
      entryMap,
      countMode,
      production
    )
    const lines = [headers, ...entries]
    return csv.buildCsvFile(name, lines)
  },

  getStatReportsHeaders(mainStats, taskTypeMap, production) {
    const taskTypeIds = getStatsTaskTypeIds(mainStats, taskTypeMap, production)
    const initialHeaders = ['Name', '', 'All', '']
    return taskTypeIds.reduce((acc, taskTypeId) => {
      if (taskTypeId !== 'all') {
        const taskTypeName = taskTypeMap.get(taskTypeId)?.name || ''
        return acc.concat([taskTypeName, ''])
      } else {
        return acc
      }
    }, initialHeaders)
  },

  getStatReportsEntries(
    mainStats,
    taskTypeMap,
    taskStatusMap,
    entryMap,
    countMode = 'count',
    production,
    { excludeStatuses = [], sortEntries = true } = {}
  ) {
    let entries = []
    const taskTypeIds = getStatsTaskTypeIds(mainStats, taskTypeMap, production)
    const entryIds = getStatsEntryIds(mainStats, entryMap)

    entryIds.forEach(entryId => {
      const taskStatusIds = getStatsTaskStatusIdsForEntry(
        mainStats,
        entryId
      ).filter(s => !excludeStatuses.includes(s))
      const total = getStatsTotalCount(
        mainStats,
        taskStatusIds,
        countMode,
        entryId
      )
      const lineMap = buildTotalLines(
        entryMap,
        taskStatusMap,
        countMode,
        mainStats,
        taskStatusIds,
        entryId,
        total
      )

      taskTypeIds.forEach(taskTypeId => {
        if (taskTypeId !== 'all') {
          const taskTypeStats = mainStats[entryId][taskTypeId]
          if (taskTypeStats) {
            const total = getStatsTotalEntryCount(
              mainStats,
              taskTypeStats,
              countMode,
              entryId,
              taskTypeId
            )
            addEntryStatusStats(
              mainStats,
              countMode,
              entryId,
              taskTypeId,
              taskStatusIds,
              total,
              lineMap
            )
          } else {
            Object.keys(mainStats[entryId].all).forEach(taskStatusId => {
              if (!excludeStatuses.includes(taskStatusId)) {
                lineMap[taskStatusId] = lineMap[taskStatusId].concat(['', ''])
              }
            })
          }
        }
      })

      const values = Object.values(lineMap)
      if (sortEntries) {
        values.sort((a, b) =>
          a[1].localeCompare(b[1], undefined, { numeric: true })
        )
      }
      entries = entries.concat(values)
      entries.push([''])
    })
    return entries
  },

  generateRetakeStatReports(
    name,
    mainStats,
    taskTypeMap,
    taskStatusMap,
    entryMap,
    countMode,
    production
  ) {
    const headers = csv.getStatReportsHeaders(
      mainStats,
      taskTypeMap,
      production
    )
    const retakeOptions = {
      excludeStatuses: ['max_retake_count', 'evolution'],
      sortEntries: false
    }
    const entries = csv.getStatReportsEntries(
      mainStats,
      taskTypeMap,
      taskStatusMap,
      entryMap,
      countMode,
      production,
      retakeOptions
    )
    const lines = [headers, ...entries]
    return csv.buildCsvFile(name, lines)
  },

  generateQuotas(
    name,
    quotas,
    people,
    countMode,
    detailLevel,
    todayYear,
    todayMonth,
    year,
    month,
    week
  ) {
    const headers = csv.getTimesheetHeaders(
      {},
      detailLevel,
      todayYear,
      todayMonth,
      year,
      month,
      week
    )
    const entries = csv.getQuotaEntries(
      quotas,
      people,
      countMode,
      detailLevel,
      headers,
      year,
      month
    )
    csv.buildCsvFile(name, entries)
  },

  getQuotaEntries(
    quotas,
    people,
    countMode,
    detailLevel,
    headers,
    year,
    month
  ) {
    const entries = [headers]
    people.forEach(person => {
      const line = [person.full_name]
      headers.forEach((h, index) => {
        if (index > 0) {
          let key
          if (detailLevel === 'day') {
            key = `${year}-${String(month).padStart(2, '0')}-${String(index).padStart(2, '0')}`
          } else if (detailLevel === 'week') {
            // in the case of week its in the format of 1999-1 not 1999-01
            key = `${year}-${index}`
          } else {
            key = `${year}-${String(index).padStart(2, '0')}`
          }
          if (
            quotas &&
            quotas[person.id] &&
            quotas[person.id][detailLevel][countMode][key]
          ) {
            let value = quotas[person.id][detailLevel][countMode][key]
            if (typeof value === 'number')
              value = Math.round((value + Number.EPSILON) * 100) / 100
            line.push(value)
          } else {
            line.push('-')
          }
        }
      })
      entries.push(line)
    })
    return entries
  },

  processCSV: async (data, config = {}) => {
    const encoding =
      typeof data === 'string' ? 'UTF-8' : await getFileEncoding(data)
    return new Promise((resolve, reject) => {
      const fail = err => {
        addReadFailure(err)
        reject(err)
      }
      Papa.parse(data, {
        encoding,
        error: fail,
        transform: value => value.trim(),
        // For a file, this runs in a FileReader callback, outside the
        // promise: a throw here would leave it pending.
        complete: results => {
          if (results.data.length) {
            resolve(results.data)
          } else {
            fail(new Error('The CSV file is empty'))
          }
        },
        ...config
      })
    })
  },

  // A file the browser could not read is the user's: the import modal says
  // so. Anything else is a bug that must stay unhandled for Sentry.
  logReadFailure: err => {
    if (!readFailures.has(err)) throw err
    console.error(err)
  }
}

const getStatsTaskTypeIds = (mainStats, taskTypeMap, production) => {
  return Object.keys(mainStats.all)
    .filter(taskTypeId => taskTypeId !== 'evolution')
    .sort((a, b) => {
      if (a === 'all') return 1
      if (b === 'all') return -1
      const taskTypeA = taskTypeMap.get(a)
      const taskTypeB = taskTypeMap.get(b)
      const taskTypeAPriority = getTaskTypePriorityOfProd(taskTypeA, production)
      const taskTypeBPriority = getTaskTypePriorityOfProd(taskTypeB, production)
      if (taskTypeAPriority === taskTypeBPriority) {
        return (taskTypeA?.name || '').localeCompare(
          taskTypeB?.name || '',
          undefined,
          {
            numeric: true
          }
        )
      }
      return taskTypeAPriority - taskTypeBPriority
    })
}

const getStatsEntryIds = (mainStats, entryMap) => {
  return Object.keys(mainStats)
    .filter(entryId => entryId === 'all' || entryMap.get(entryId))
    .sort((a, b) => {
      if (a === 'all') return -1
      if (b === 'all') return 1
      return entryMap
        .get(a)
        .name.localeCompare(entryMap.get(b).name, undefined, {
          numeric: true
        })
    })
}

const getStatsTotalCount = (mainStats, taskStatusIds, countMode, entryId) => {
  let total = 0
  taskStatusIds.forEach(taskStatusId => {
    const taskStatusStats = mainStats[entryId].all[taskStatusId]
    total += taskStatusStats[countMode]
  })
  return total
}

const getStatsTaskStatusIdsForEntry = (mainStats, entryId) => {
  return Object.keys(mainStats[entryId].all)
}

const getStatsTotalEntryCount = (
  mainStats,
  taskTypeStats,
  countMode,
  entryId,
  taskTypeId
) => {
  let total = 0
  Object.keys(taskTypeStats).forEach(taskStatusId => {
    if (!['max_retake_count', 'evolution'].includes(taskStatusId)) {
      const taskStatusStats = mainStats[entryId][taskTypeId][taskStatusId]
      total += taskStatusStats[countMode]
    }
  })
  return total
}

const buildTotalLines = (
  entryMap,
  taskStatusMap,
  countMode,
  mainStats,
  taskStatusIds,
  entryId,
  total
) => {
  const lineMap = {}
  taskStatusIds.forEach(taskStatusId => {
    const taskStatus = taskStatusMap.get(taskStatusId)
    const taskStatusName = taskStatus ? taskStatus.name : taskStatusId
    const entry = entryMap.get(entryId)
    const name = entry ? entry.name : 'All'
    const taskStatusStats = mainStats[entryId].all[taskStatusId]
    const count = taskStatusStats[countMode]
    const percentage = getPercentage(count, total)
    lineMap[taskStatusId] = [
      name,
      taskStatusName,
      count || '0',
      `${percentage}%`
    ]
  })
  return lineMap
}

const addEntryStatusStats = (
  mainStats,
  countMode,
  entryId,
  taskTypeId,
  taskStatusIds,
  total,
  lineMap
) => {
  taskStatusIds.forEach(taskStatusId => {
    const taskStatusStats = mainStats[entryId][taskTypeId][taskStatusId]
    let count = 0
    if (taskStatusStats) count = taskStatusStats[countMode]
    const percentage = getPercentage(count, total)
    lineMap[taskStatusId] = lineMap[taskStatusId].concat([
      count || '0',
      `${percentage}%`
    ])
  })
}

export default csv
